class Parent {
    // Instance method for Overriding
    public void showMessage() {
        System.out.println("Parent instance method");
    }

    // Static method for Hiding
    public static void display() {
        System.out.println("Parent static method");
    }
}

class Child extends Parent {
    @Override
    public void showMessage() {
        System.out.println("Child instance method (Overridden)");
    }

    // This hides Parent.display(), it does not override it
    public static void display() {
        System.out.println("Child static method (Hidden)");
    }
}

public class DispatchDemo {
    public static void main(String[] args) {
        Parent obj = new Child();
        obj.showMessage(); // Outputs: Child instance method (Dynamic Dispatch)
        obj.display();     // Outputs: Parent static method (Static Binding)
    }
}
